C++
```c++
#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int maxn = 1e5 + 5;
const int mod = 1e9 + 7;
ll ksm (ll a , ll b){
    ll ans = 1 , base = a;
    while (b){
        if (b & 1) ans = ans * base % mod;
        base = base * base % mod;
        b >>= 1;
    }
    return ans;
}
// 四个数组对应上面得四个状态
ll bk[maxn] , f[maxn] , g[maxn] , dp[maxn];
int main (){
    int n , k;
    cin >> n >> k;
    for (int i = 1 ; i <= n ; i++){
        int x; cin >> x;
        bk[x] ++;
    }
    // 参考上述f的转移方程
    for (int i = 1 ; i < maxn ; i++){
        for (int j = i ; j < maxn ; j += i){
            f[i] += bk[j];
        }
    }
    // 参考上述g的转移方程
    for (int i = 1 ; i < maxn ; i++){
        g[i] = (ksm(2 , f[i]) - 1 + mod) % mod;
    }
    // 参考上述dp的转移方程
    for (int i = maxn - 1 ; i >= 1 ; i --){
        dp[i] = g[i];
        for (int j = i + i ; j < maxn ; j += i){
            dp[i] = (dp[i] - dp[j] + mod) % mod;
        }
    }
    cout << dp[k] <<endl;
	return 0;
}
```

Java

```java
import java.util.*;
class Main{
    static int mod = 1000000007;
    public static void main(String[] args){
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt(), k = scanner.nextInt();
        int[] a = new int[n];
        for(int i=0;i<n;i++){
            a[i] = scanner.nextInt();
        }
        int maxn = 100002;
        long[] cnt = new long[maxn], mulitiCnt = new long[maxn], subset = new long[maxn], dp = new long[maxn];
        for(int i=0;i<n;i++){
            cnt[a[i]]++;
        }
        for(int i=1;i<maxn;i++){
            for(int j=i;j<maxn;j += i){
                mulitiCnt[i] += cnt[j];
            }
        }
        for(int i=1;i<maxn;i++){
            subset[i] = (ksm(2L, mulitiCnt[i]) - 1 + mod) % mod;
        }
        for(int i=maxn-1;i>=1;i--){
            dp[i] = subset[i];
            for(int j=i+i;j<maxn;j+=i){
                dp[i] = (dp[i] - dp[j] + mod) % mod;
            }
        }
        System.out.println(dp[k]);
    }

    public static long ksm(long a, long b){
        long res = 1L;
        while(b > 0){
            if((b & 1) == 1){
                res = (res * a) % mod;
            }
            b >>= 1;
            a = (a * a) % mod;
        }
        return res;
    }
}
