def solve(n,k,arr):
    mx = max(arr)
    cc = [0]*(mx+1)
    for a in arr: cc[a] += 1
    fs = [1]*(n+1)
    MOD = 10**9+7
    for i in range(1,n+1):
        fs[i] = (2*fs[i-1])%MOD 
    for i in range(k,mx+1):
        for j in range(i*2,mx+1,i):
            cc[i] += cc[j]
    dp = [0]*(mx+1)
    ans = 0
    for i in range(k,mx+1)[::-1]:
        dp[i] = fs[cc[i]]-1
        for j in range(i*2,mx+1,i):
            dp[i] -= dp[j]
        dp[i] %= MOD 
    return dp[k] 


def main():
    for _ in range(1):
        n, k = list(map(int,input().split()))
        arr = list(map(int,input().split()))
        print(solve(n,k,arr))
